#!/usr/bin/env python3
"""Generate the hash-locked install file for a published hola-opt release.

Reads one GitHub release object (as returned by
``gh api repos/blackrock/HOLA/releases/tags/<tag>``) from stdin and writes a
pip requirements file to stdout that pins the release version and lists the
SHA-256 digest GitHub recorded for every wheel:

    gh api repos/blackrock/HOLA/releases/tags/v1.0.1-rc8 \
        | python3 .github/scripts/build_install_requirements.py \
        > install/hola-opt-requirements.txt

The file resolves hola-opt only from the project index and only as a wheel, so
installing it never consults a public index and never needs build dependencies
from one. Stdlib-only; the pure helpers are unit tested.
"""

from __future__ import annotations

import json
import re
import sys

PROJECT = "hola-opt"
INDEX_URL = "https://blackrock.github.io/HOLA/simple/"
WHEEL_RE = re.compile(r"^hola_opt-(?P<version>[^-]+)-.+\.whl$")
DIGEST_RE = re.compile(r"^sha256:(?P<hex>[0-9a-f]{64})$")


def wheel_digests(release: dict) -> tuple[str, list[tuple[str, str]]]:
    """Return ``(version, [(wheel filename, sha256 hex), ...])`` for a release.

    Raises ``ValueError`` when the release has no wheels, when wheels disagree
    on the version, or when any wheel lacks a recorded SHA-256 digest. A
    partial file would silently drop a platform, so every failure is fatal.
    """
    wheels: list[tuple[str, str]] = []
    versions: set[str] = set()
    for asset in release.get("assets", []):
        name = asset.get("name", "")
        match = WHEEL_RE.fullmatch(name)
        if match is None:
            continue
        digest = DIGEST_RE.fullmatch(asset.get("digest") or "")
        if digest is None:
            raise ValueError(f"{name}: release asset has no sha256 digest")
        versions.add(match["version"])
        wheels.append((name, digest["hex"]))
    if not wheels:
        raise ValueError("release has no hola_opt wheels")
    if len(versions) != 1:
        raise ValueError(f"wheels disagree on the version: {sorted(versions)}")
    return versions.pop(), sorted(wheels)


def render_requirements(tag: str, version: str, wheels: list[tuple[str, str]]) -> str:
    """Render the requirements file for one release."""
    lines = [
        f"# Hash-locked install of the {PROJECT} {version} wheels built by the release",
        f"# workflow of https://github.com/blackrock/HOLA (release {tag}).",
        "#",
        "#     pip install --require-hashes -r install/hola-opt-requirements.txt",
        "#",
        f"# pip resolves {PROJECT} only from the project index below and rejects any file",
        "# whose SHA-256 is not listed here, so a same-named project on another index",
        "# cannot satisfy this install. Wheels only: on a platform without a wheel,",
        "# build from source instead (docs/getting-started.md).",
        "#",
        "# Generated by .github/scripts/build_install_requirements.py. Do not edit.",
        "--require-hashes",
        f"--index-url {INDEX_URL}",
        f"--only-binary {PROJECT}",
        f"{PROJECT}=={version} \\",
    ]
    for index, (_name, digest) in enumerate(wheels):
        continuation = " \\" if index + 1 < len(wheels) else ""
        lines.append(f"    --hash=sha256:{digest}{continuation}")
    return "\n".join(lines) + "\n"


def main() -> None:
    release = json.load(sys.stdin)
    try:
        version, wheels = wheel_digests(release)
    except ValueError as exc:
        raise SystemExit(f"error: {exc}") from exc
    sys.stdout.write(render_requirements(release.get("tag_name", "?"), version, wheels))


if __name__ == "__main__":
    main()
